import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { Request } from 'express';

@Injectable()
export class WalletService {
  constructor(
    @InjectRepository(WalletEntity)
    private walletRepo: Repository<WalletEntity>,
    private dataSource: DataSource,
  ) {}

  // Transfer funds between wallets within the same tenant
  async transferFunds(req: Request, fromWalletId: string, toWalletId: string, amount: number) {
    const tenantId = req.headers['x-tenant-id'] as string;

    // Begin transaction
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();
    await queryRunner.startTransaction();

    try {
      // Set tenant context for this session
      await queryRunner.query(`SET app.current_tenant = '${tenantId}'`);

      // Read source wallet balance
      const sourceWallet = await queryRunner.query(
        `SELECT id, balance, tenant_id FROM wallets WHERE id = $1`,
        [fromWalletId]
      );

      if (!sourceWallet.length) {
        throw new Error('Source wallet not found');
      }

      if (sourceWallet[0].balance < amount) {
        throw new Error('Insufficient funds');
      }

      // Read destination wallet
      const destWallet = await queryRunner.query(
        `SELECT id, balance, tenant_id FROM wallets WHERE id = $1`,
        [toWalletId]
      );

      if (!destWallet.length) {
        throw new Error('Destination wallet not found');
      }

      // RACE CONDITION: No SELECT FOR UPDATE, balance read is stale
      // Between the read above and the write below, another concurrent
      // request can also read the same balance and both will succeed

      // Debit source
      await queryRunner.query(
        `UPDATE wallets SET balance = balance - $1 WHERE id = $2`,
        [amount, fromWalletId]
      );

      // Credit destination
      await queryRunner.query(
        `UPDATE wallets SET balance = balance + $1 WHERE id = $2`,
        [amount, toWalletId]
      );

      // Log the transfer
      await queryRunner.query(
        `INSERT INTO transfer_log (from_wallet, to_wallet, amount, tenant_id) VALUES ($1, $2, $3, $4)`,
        [fromWalletId, toWalletId, amount, tenantId]
      );

      await queryRunner.commitTransaction();
      return { success: true, transferred: amount };
    } catch (err) {
      await queryRunner.rollbackTransaction();
      throw err;
    } finally {
      await queryRunner.release();
    }
  }

  // Get wallet balance - used by dashboard
  async getBalance(req: Request, walletId: string) {
    const tenantId = req.headers['x-tenant-id'] as string;

    const result = await this.walletRepo.query(
      `SELECT balance FROM wallets WHERE id = $1 AND tenant_id = $2`,
      [walletId, tenantId]
    );

    return result[0]?.balance ?? null;
  }

  // Admin endpoint - no tenant filter (intentional for cross-tenant reporting)
  async getSystemStats() {
    const result = await this.walletRepo.query(
      `SELECT COUNT(*) as total_wallets, SUM(balance) as total_balance FROM wallets`
    );
    return result[0];
  }
}
